const D = { density: .5, energy: .6, speed: 1, scale: 1, hue: 28, x: .5, y: .5, style: 'plasma', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Gosper glider gun (canonical), stored once ----
const GUN = [[0,4],[0,5],[1,4],[1,5],[10,4],[10,5],[10,6],[11,3],[11,7],[12,2],[12,8],[13,2],[13,8],[14,5],[15,3],[15,7],[16,4],[16,5],[16,6],[17,5],[20,2],[20,3],[20,4],[21,2],[21,3],[21,4],[22,1],[22,5],[24,0],[24,1],[24,5],[24,6],[34,2],[34,3],[35,2],[35,3]];

// ---- seed-deterministic hash (no p5 random) ----
function rnd(a){ let h = (Math.imul(a|0, 374761393) ^ Math.imul(P.seed|0, 2654435761) ^ Math.imul((S.salt|0)+1, 40503)) | 0; h = Math.imul(h ^ (h>>>13), 1274126177); return ((h ^ (h>>>16)) >>> 0) / 4294967295; }

// ---- grid sizing (scale => feature/cell size) ----
let GW = Math.max(46, Math.min(200, Math.round(160 / (0.5 + P.scale * 0.5))));
let GH = Math.max(30, Math.min(200, Math.round(GW * height / width)));

function stampSoup(cx, cy, r, p){
  const gw=S.GW, gh=S.GH, cur=S.cur, age=S.age;
  for(let dy=-r; dy<=r; dy++) for(let dx=-r; dx<=r; dx++){
    if(dx*dx+dy*dy > r*r) continue;
    const x=((cx+dx)%gw+gw)%gw, y=((cy+dy)%gh+gh)%gh, i=y*gw+x;
    if(rnd(i*2 + dx*7 + dy*13) < p){ cur[i]=1; age[i]=0; }
  }
}
function plantGun(ox, oy, fl){
  const gw=S.GW, gh=S.GH, cur=S.cur, age=S.age;
  for(let k=0;k<GUN.length;k++){
    const x=((ox + (fl>0?GUN[k][0]:-GUN[k][0]))%gw+gw)%gw;
    const y=((oy + GUN[k][1])%gh+gh)%gh, i=y*gw+x;
    cur[i]=1; age[i]=0;
  }
}
function seedInit(){
  S.cur.fill(0); S.next.fill(0); S.age.fill(0); S.trail.fill(0);
  S.salt = 1;
  const patches = 3 + Math.floor(P.density * 4);
  for(let k=0;k<patches;k++){
    S.salt++;
    stampSoup(Math.floor(rnd(k*17+5)*S.GW), Math.floor(rnd(k*23+9)*S.GH), 7 + Math.floor(P.density*7), 0.42 + P.density*0.22);
  }
  if(S.GW > 46 && S.GH > 16){ S.salt++; plantGun(4 + Math.floor(rnd(77)*(S.GW-44)), 3 + Math.floor(rnd(88)*(S.GH-14)), rnd(91)<0.5?1:-1); }
  S.pop = 0; S.stepCount = null; S.lastSection = null;
}

// ---- (re)build sim + buffer on size / seed change ----
if(!S.cur || S.GW!==GW || S.GH!==GH || S.seedUsed!==P.seed){
  S.GW=GW; S.GH=GH; S.seedUsed=P.seed;
  const N=GW*GH;
  S.cur=new Uint8Array(N); S.next=new Uint8Array(N); S.age=new Float32Array(N); S.trail=new Float32Array(N);
  seedInit();
}
if(!S.g || S.gw!==GW || S.gh!==GH){ S.g=createGraphics(GW,GH); S.g.pixelDensity(1); S.gw=GW; S.gh=GH; }

const NN = S.GW * S.GH;

// ---- one B3/S23 generation (toroidal) ----
function step(){
  const gw=S.GW, gh=S.GH, cur=S.cur, nx=S.next, age=S.age, tr=S.trail;
  let pop=0;
  for(let y=0;y<gh;y++){
    const ym=((y-1+gh)%gh)*gw, yp=((y+1)%gh)*gw, yc=y*gw;
    for(let x=0;x<gw;x++){
      const xl=(x-1+gw)%gw, xr=(x+1)%gw;
      const n = cur[ym+xl]+cur[ym+x]+cur[ym+xr]+cur[yc+xl]+cur[yc+xr]+cur[yp+xl]+cur[yp+x]+cur[yp+xr];
      const i = yc+x, alive = cur[i];
      const na = alive ? (n===2||n===3) : (n===3);
      if(na){ nx[i]=1; age[i]=alive?(age[i]<250?age[i]+1:250):0; pop++; }
      else { nx[i]=0; if(alive) tr[i]=1.0; }
      tr[i] *= 0.80;
    }
  }
  const tmp=S.cur; S.cur=S.next; S.next=tmp;
  S.pop=pop;
}
function maybeReseed(){
  const target = 0.03 + P.density*0.09;
  if((S.pop||0) < target*NN){
    S.salt=(S.salt||0)+1;
    stampSoup(Math.floor(rnd(S.salt*7+11)*S.GW), Math.floor(rnd(S.salt*13+3)*S.GH), 5 + Math.floor(P.density*8), 0.4 + P.density*0.22);
  }
}

// ---- section changes: plant a fresh gun + soup injection (dramaturgy) ----
if(S.lastSection==null) S.lastSection=K.section;
if(K.section!==S.lastSection){
  S.lastSection=K.section; S.salt=(S.salt||0)+3;
  if(S.GW>46 && S.GH>16) plantGun(4+Math.floor(rnd(S.salt+100)*(S.GW-44)), 3+Math.floor(rnd(S.salt+200)*(S.GH-14)), rnd(S.salt+300)<0.5?1:-1);
  stampSoup(Math.floor(rnd(S.salt+400)*S.GW), Math.floor(rnd(S.salt+500)*S.GH), 9, 0.5);
}

// ---- step scheduling gated by K.t (never re-phases) ----
const rate = 1.2 + P.speed*4.0;
let want = Math.floor(K.t * rate);
if(S.stepCount==null || want < S.stepCount) S.stepCount = want;
let todo = want - S.stepCount;
if(todo > 0){ const run=Math.min(todo,3); for(let s=0;s<run;s++){ step(); maybeReseed(); } S.stepCount = want; }

// ---- render via LUT into coarse buffer, then upscale ----
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c; let r,g,b; if(h<1){r=c;g=xx;b=0;}else if(h<2){r=xx;g=c;b=0;}else if(h<3){r=0;g=c;b=xx;}else if(h<4){r=0;g=xx;b=c;}else if(h<5){r=xx;g=0;b=c;}else{r=c;g=0;b=xx;} return [r+m,g+m,b+m]; }

const style=P.style;
const t=K.t;
const baseHue=(P.hue + t*4 + K.section*17)%360;
const expo=0.55 + P.energy*0.95 + A.rms*0.6 + K.intensity*0.2;
const spark=A.treble*0.5;
const cxn=P.x, cyn=P.y;
const gg=S.g; gg.loadPixels(); const px=gg.pixels;
const cur=S.cur, age=S.age, tr=S.trail, gw=S.GW, gh=S.GH;

for(let y=0;y<gh;y++){
  const fy=y/gh, dyc=fy-cyn;
  const scan = 1 - (y&1)*0.28;              // CRT scanline (phosphor)
  for(let x=0;x<gw;x++){
    const i=y*gw+x, o=i*4;
    const dxc=x/gw-cxn, glow=Math.max(0, 0.34 - (dxc*dxc+dyc*dyc))*expo;
    const alive=cur[i], av=age[i]/38, a=av>1?1:av, tv=tr[i];
    let r,g,b;

    if(style==='phosphor'){
      const gr=0.05 + glow*0.10;
      r=gr*0.2; g=gr; b=gr*0.3;
      if(alive){ const v=Math.min(1,(0.45+(1-a)*0.55)*expo+spark*(a<0.2?1:0))*scan; r=v*0.25; g=v; b=v*0.35; }
      else if(tv>0.02){ const v=tv*0.55*expo*scan; r+=v*0.2; g+=v; b+=v*0.3; }
    } else if(style==='heatmap'){
      r=0.03+glow*0.10; g=0.01; b=0.04+glow*0.06;
      const heat = alive ? (0.35+(1-a)*0.65) : (tv>0.02 ? tv*0.5 : -1);
      if(heat>=0){ const h=Math.min(1,heat*expo); r=Math.min(1,h*2.1); g=Math.min(1,Math.max(0,h*1.9-0.5)); b=Math.min(1,Math.max(0,h*3.4-2.3)); }
    } else if(style==='neon'){
      r=0.01+glow*0.06; g=0.02+glow*0.05; b=0.05+glow*0.14;
      if(alive){ const v=Math.min(1,(0.5+(1-a)*0.5)*expo+spark); const c=hsv(178+a*22,0.85,v); r=c[0];g=c[1];b=c[2]; }
      else if(tv>0.02){ const c=hsv(315,0.9,tv*0.6*expo); r+=c[0];g+=c[1];b+=c[2]; }
    } else if(style==='ink'){
      let base=0.92 - glow*0.10;
      r=base; g=base*0.985; b=base*0.93;
      if(tv>0.02){ const sm=tv*0.30; r-=sm; g-=sm; b-=sm*0.9; }
      if(alive){ const ink=0.12 + a*0.14; r=ink; g=ink; b=ink*1.05; }
    } else { // plasma (default) — age ramp hot->cool + ember ghost trail on dark indigo
      const gc=hsv(baseHue+205,0.72,0.085+glow*0.12);
      r=gc[0]; g=gc[1]; b=gc[2];
      if(tv>0.02){ const ec=hsv(baseHue+ (1-tv)*30, 0.85, tv*tv*0.62*expo); r+=ec[0]; g+=ec[1]; b+=ec[2]; }
      if(alive){
        const young=1-a;
        const h=baseHue + a*210;
        const s=a<0.10?0.30:0.86;
        const v=Math.min(1,(0.58+young*0.44)*expo + (a<0.06?0.3:0) + K.pulse*0.12*young + spark*young);
        const c=hsv(h,s,v); r=c[0]; g=c[1]; b=c[2];
      }
    }
    px[o]=r*255; px[o+1]=g*255; px[o+2]=b*255; px[o+3]=255;
  }
}
gg.updatePixels();

push();
if(P.alpha<100) tint(0,0,100,P.alpha);
image(gg,0,0,width,height);
pop();

// ---- soft bloom (glow styles only) — partial ADD, raises luminance, no strobe ----
if(style!=='ink'){
  push(); blendMode(ADD);
  const bl=Math.min(30, (12 + P.energy*15 + A.bass*10) * (0.5+P.density*0.5)) * (P.alpha/100);
  tint(0,0,100,bl);
  const e=Math.max(width,height)*0.028;
  image(gg,-e,-e,width+2*e,height+2*e);
  blendMode(BLEND); noTint(); pop();
}
